// Извлекаем ссылки из сообщения
const message = $input.item.json.message;
const text = message.text || '';
const chatId = message.chat.id;
const messageId = message.message_id;
const userName = message.from.first_name || 'User';

// Регулярное выражение для поиска URL
const urlRegex = /(https?:\/\/[^\s]+)/gi;
const links = text.match(urlRegex) || [];

// ВАЖНО: всегда возвращаем массив
if (links.length === 0) {
  // Если нет ссылок, возвращаем один элемент с ошибкой
  return [{
    json: {
      chatId,
      messageId,
      userName,
      error: 'no_links',
      text: text
    }
  }];
}

// Если есть ссылки, возвращаем каждую как отдельный элемент
return links.map(link => ({
  json: {
    chatId,
    messageId,
    userName,
    link: link.trim(),
    originalText: text
  }
}));

// Извлекаем Google Drive File ID
const link = $input.item.json.link;
let fileId = '';

// Расширенные паттерны для разных форматов ссылок Google Drive
const patterns = [
  /\/file\/d\/([a-zA-Z0-9_-]+)/,
  /\/open\?id=([a-zA-Z0-9_-]+)/,
  /[?&]id=([a-zA-Z0-9_-]+)/,
  /uc\?id=([a-zA-Z0-9_-]+)/,
  /\/d\/([a-zA-Z0-9_-]+)/,
  /drive\.google\.com\/.*\/([a-zA-Z0-9_-]{25,})/
];

// Пробуем все паттерны
for (const pattern of patterns) {
  const match = link.match(pattern);
  if (match && match[1]) {
    fileId = match[1];
    break;
  }
}

// Если ID не найден, возвращаем ошибку
if (!fileId) {
  return [{
    json: {
      ...($input.item.json),
      error: 'invalid_google_link',
      errorMessage: 'Не удалось извлечь ID из ссылки Google Drive. Проверьте формат ссылки.'
    }
  }];
}

// Успешно извлекли ID
return [{
  json: {
    ...($input.item.json),
    fileId: fileId,
    downloadUrl: `https://drive.google.com/uc?export=download&id=${fileId}`
  }
}];

// Скачиваем файл через хелпер n8n
const downloadUrl = $input.item.json.href;

if (!downloadUrl) {
  throw new Error('Download URL (href) not found in input');
}

// Используем встроенный хелпер для скачивания с автоматическим следованием редиректам
const response = await this.helpers.httpRequest({
  method: 'GET',
  url: downloadUrl,
  encoding: null, // Важно: null для binary данных
  followRedirect: true,
  returnFullResponse: true
});

// Получаем имя файла из URL (парсим вручную, без URLSearchParams)
let filename = 'downloaded_file';
const filenameMatch = downloadUrl.match(/[?&]filename=([^&]+)/);
if (filenameMatch && filenameMatch[1]) {
  filename = decodeURIComponent(filenameMatch[1]);
}

// Определяем MIME тип
const contentType = response.headers['content-type'] || 'application/octet-stream';

// Создаем binary данные
const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(response.body),
  filename,
  contentType
);

return [{
  json: {
    ...($input.item.json),
    downloadedFile: filename,
    mimeType: contentType,
    fileSize: response.body.length
  },
  binary: {
    data: binaryData
  }
}];

// Объединяем данные с обеих веток (Google и Yandex)
const item = $input.item;

// Определяем MIME тип из заголовков или расширения файла
const contentType = item.binary?.data?.mimeType || '';
let fileType = 'unknown';

if (contentType.includes('image/')) {
  fileType = 'image';
} else if (contentType.includes('pdf') || contentType === 'application/pdf') {
  fileType = 'pdf';
} else if (contentType.includes('video/')) {
  fileType = 'video';
}

// ✅ Возвращаем массив
return [{
  json: {
    ...item.json,
    fileType: fileType,
    mimeType: contentType
  },
  binary: item.binary
}];

// Извлекаем текст из ответа Vision API
const responses = $input.item.json.responses || [];

if (responses.length === 0 || !responses[0].fullTextAnnotation) {
  // ✅ Возвращаем массив даже при ошибке
  return [{
    json: {
      ...($input.item.json),
      recognizedText: '',
      error: 'no_text_detected'
    }
  }];
}

let text = responses[0].fullTextAnnotation.text || '';

// Нормализуем текст
// Убираем лишние пробелы и переводы строк
text = text.replace(/\s+/g, ' ');
text = text.replace(/\n+/g, '\n');
text = text.trim();

// ✅ Возвращаем массив
return [{
  json: {
    ...($input.item.json),
    recognizedText: text,
    rawVisionResponse: responses[0]
  }
}];

// Парсим метрики из распознанного текста
const text = $input.item.json.recognizedText || '';
const metrics = {};
let platform = 'Unknown';

// Определяем платформу
if (text.match(/instagram/i)) platform = 'Instagram';
else if (text.match(/telegram/i)) platform = 'Telegram';
else if (text.match(/vk|вконтакте/i)) platform = 'VK';
else if (text.match(/youtube/i)) platform = 'YouTube';
else if (text.match(/tiktok/i)) platform = 'TikTok';

// Паттерны для извлечения метрик
const patterns = {
  followers: [
    /подписчик(?:ов|и)?[:\s]+(\d[\d\s,]+)/i,
    /followers?[:\s]+(\d[\d\s,]+)/i,
    /subscriber(?:s)?[:\s]+(\d[\d\s,]+)/i
  ],
  reach: [
    /охват[:\s]+(\d[\d\s,]+)/i,
    /reach[:\s]+(\d[\d\s,]+)/i,
    /coverage[:\s]+(\d[\d\s,]+)/i
  ],
  impressions: [
    /показ(?:ы|ов)?[:\s]+(\d[\d\s,]+)/i,
    /impression(?:s)?[:\s]+(\d[\d\s,]+)/i,
    /views?[:\s]+(\d[\d\s,]+)/i,
    /просмотр(?:ы|ов)?[:\s]+(\d[\d\s,]+)/i
  ],
  engagement: [
    /вовлечен(?:ие|ность)[:\s]+(\d[\d\s,]+)/i,
    /engagement[:\s]+(\d[\d\s,]+)/i
  ],
  likes: [
    /лайк(?:ов|и)?[:\s]+(\d[\d\s,]+)/i,
    /like(?:s)?[:\s]+(\d[\d\s,]+)/i
  ],
  comments: [
    /комментари(?:ев|и)?[:\s]+(\d[\d\s,]+)/i,
    /comment(?:s)?[:\s]+(\d[\d\s,]+)/i
  ],
  shares: [
    /репост(?:ов|ы)?[:\s]+(\d[\d\s,]+)/i,
    /share(?:s)?[:\s]+(\d[\d\s,]+)/i
  ],
  clicks: [
    /клик(?:ов|и)?[:\s]+(\d[\d\s,]+)/i,
    /click(?:s)?[:\s]+(\d[\d\s,]+)/i
  ],
  ctr: [
    /ctr[:\s]+(\d+[.,]?\d*)\s*%?/i,
    /кликабельность[:\s]+(\d+[.,]?\d*)\s*%?/i
  ]
};

// Функция для очистки чисел
function cleanNumber(str) {
  return parseInt(str.replace(/[\s,]/g, ''), 10);
}

function cleanPercent(str) {
  return parseFloat(str.replace(',', '.'));
}

// Извлекаем метрики
for (const [metric, regexes] of Object.entries(patterns)) {
  for (const regex of regexes) {
    const match = text.match(regex);
    if (match && match[1]) {
      if (metric === 'ctr') {
        metrics[metric] = cleanPercent(match[1]);
      } else {
        metrics[metric] = cleanNumber(match[1]);
      }
      break;
    }
  }
}

// Проверяем полноту данных
const foundMetrics = Object.keys(metrics).length;
const status = foundMetrics >= 3 ? 'complete' : 'partial';

// ✅ Возвращаем массив
return [{
  json: {
    ...($input.item.json),
    platform,
    metrics,
    status,
    foundMetricsCount: foundMetrics
  }
}];

// Форматируем ответ для пользователя
const data = $input.item.json;
const platform = data.platform || 'Unknown';
const metrics = data.metrics || {};
const status = data.status || 'error';

// Функция для форматирования числа с пробелами
function formatNumber(num) {
  if (num === undefined) return 'н/д';
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}

let response = `📊 **Статистика (${platform})**\n\n`;

// Добавляем метрики
if (metrics.followers) {
  response += `👥 Подписчики: ${formatNumber(metrics.followers)}\n`;
}
if (metrics.reach) {
  response += `📈 Охват: ${formatNumber(metrics.reach)}\n`;
}
if (metrics.impressions) {
  response += `👁 Показы: ${formatNumber(metrics.impressions)}\n`;
}
if (metrics.engagement) {
  response += `💬 Вовлечённость: ${formatNumber(metrics.engagement)}\n`;
}
if (metrics.likes) {
  response += `❤️ Лайки: ${formatNumber(metrics.likes)}\n`;
}
if (metrics.comments) {
  response += `💭 Комментарии: ${formatNumber(metrics.comments)}\n`;
}
if (metrics.shares) {
  response += `🔄 Репосты: ${formatNumber(metrics.shares)}\n`;
}
if (metrics.clicks) {
  response += `🖱 Клики: ${formatNumber(metrics.clicks)}\n`;
}
if (metrics.ctr) {
  response += `📊 CTR: ${metrics.ctr}%\n`;
}

// Добавляем предупреждение если данные неполные
if (status === 'partial') {
  response += `\n⚠️ Некоторые данные не удалось распознать. Для более точного результата отправьте более чёткий скриншот.`;
} else if (Object.keys(metrics).length === 0) {
  response += `❌ Не удалось распознать метрики.\n\nПожалуйста, отправьте более чёткое изображение со статистикой.`;
}

// ✅ Возвращаем массив
return [{
  json: {
    ...data,
    formattedResponse: response
  }
}];

// Получаем бинарные данные
const item = $input.item;

// Определяем имя бинарного свойства (может быть 'data' или другое)
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('Binary data not found in item');
}

const binaryKey = binaryKeys[0]; // Берем первое доступное свойство
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);

// Конвертируем в base64
const imageBase64 = buffer.toString('base64');

// Проверяем что base64 не начинается с '='
if (imageBase64.startsWith('=')) {
  throw new Error('Invalid base64 encoding detected');
}

return [{
  json: {
    ...(item.json),
    imageBase64: imageBase64,
    imageSize: buffer.length,
    binaryKey: binaryKey // Для отладки
  }
}];
